const body = $('Webhook').first().json.body || {};
if (!body.project_id) { const e = { valid: false, error: 'project_id obligatorio' }; return [{ json: e }]; }
if (!body.description || body.description.toString().trim().length < 5) {
  const e = { valid: false, error: 'description (texto > 5 chars) obligatorio' };
  return [{ json: e }];
}
let photoUrls = body.photo_urls;
if (!photoUrls && body.photo_url) photoUrls = [body.photo_url];
if (!Array.isArray(photoUrls)) photoUrls = [];
photoUrls = photoUrls.filter(u => typeof u === 'string' && u.startsWith('http')).slice(0, 5);
const out = {
  valid: true,
  project_id: body.project_id,
  description: body.description.toString().slice(0, 2000),
  photo_urls: photoUrls,
  reporter: body.reporter || 'cliente',
  client_contact: body.client_contact || null,
  started_at: Date.now()
};
return [{ json: out }];

const ctx = $input.first().json.context || {};
const input = $('Validate').first().json;
const daysSinceHandover = ctx.days_since_handover === null || ctx.days_since_handover === undefined
  ? null
  : Math.round(ctx.days_since_handover);

const systemPrompt = 'Eres un experto en patologia de la edificacion y postventa LOE. Clasificas incidencias post-entrega para enrutarlas al gremio responsable. Conoces los plazos LOE: 1 anio acabados, 3 anios habitabilidad/instalaciones, 10 anios estructura. Respondes SOLO con JSON valido sin markdown.';

const userText = [
  'Analiza esta incidencia post-entrega del proyecto "' + (ctx.project_name || '?') + '" (tipo: ' + (ctx.project_type || '?') + ').',
  '',
  'DESCRIPCION CLIENTE:',
  input.description,
  '',
  daysSinceHandover !== null
    ? 'DIAS DESDE ENTREGA: ' + daysSinceHandover + ' dias'
    : 'FECHA DE ENTREGA: no registrada (asumir reciente)',
  '',
  'Devuelve JSON exacto:',
  '{',
  '  "category": "acabado|habitabilidad|estructura|instalaciones|otro",',
  '  "responsible_trade": "albanileria|fontaneria|electricidad|carpinteria|pintura|climatizacion|sanitarios|otros",',
  '  "severity": "low|medium|high|urgent",',
  '  "loe_period": 1|3|10,',
  '  "vision_summary": "2-3 frases describiendo lo visible y la causa probable",',
  '  "action_recommended": "qué deberia hacer el gremio",',
  '  "confidence": "low|medium|high"',
  '}',
  '',
  'Reglas:',
  '- LOE 1 anio: pintura, juntas, sellados, defectos esteticos, mecanismos sueltos.',
  '- LOE 3 anios: humedades no estructurales, fugas, fallos de instalacion, ventilacion deficiente, acustica.',
  '- LOE 10 anios: fisuras estructurales, asentamientos, problemas de cimentacion, cubierta, fachadas portantes.',
  '- severity "urgent" si hay riesgo inmediato (gas, electrico, fuga grave, riesgo estructural).',
  '- Si no hay foto o info insuficiente: confidence: "low".'
].filter(Boolean).join('\n');

const contentArr = [{ type: 'text', text: userText }];
for (const url of input.photo_urls) {
  contentArr.push({ type: 'image_url', image_url: { url: url, detail: 'high' } });
}

const payload = {
  model: 'gpt-4o',
  max_tokens: 1000,
  temperature: 0.1,
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: contentArr }
  ]
};
return [{ json: { project_id: input.project_id, client_id: ctx.client_id || null, project_name: ctx.project_name, description: input.description, photo_urls: input.photo_urls, reporter: input.reporter, client_contact: input.client_contact, days_since_handover: daysSinceHandover, payload: payload, started_at: input.started_at } }];

const llm = $input.first().json;
const built = $('Build Vision Prompt').first().json;
const content = llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content || '';
const usage = llm.usage || {};
const tokensIn = usage.prompt_tokens || 0;
const tokensOut = usage.completion_tokens || 0;
const cost = (tokensIn / 1000) * 0.0025 + (tokensOut / 1000) * 0.01;

let parsed = {};
try {
  const m = content.match(/\{[\s\S]*\}/);
  if (m) parsed = JSON.parse(m[0]);
} catch (e) {
  parsed = { confidence: 'low', vision_summary: 'parse error: ' + e.message };
}

const loeYears = parsed.loe_period || 1;
const daysSince = built.days_since_handover;
const underWarranty = daysSince === null || daysSince <= (loeYears * 365);

const out = {
  project_id: built.project_id,
  client_id: built.client_id,
  description: built.description,
  photo_urls: built.photo_urls,
  reporter: built.reporter,
  client_contact: built.client_contact,
  category: parsed.category || 'otro',
  responsible_trade: parsed.responsible_trade || 'otros',
  severity: parsed.severity || 'medium',
  loe_period: loeYears,
  under_warranty: underWarranty,
  days_since_handover: daysSince,
  vision_summary: parsed.vision_summary || '',
  vision_raw: parsed,
  llm_model: llm.model || 'gpt-4o',
  llm_tokens_in: tokensIn,
  llm_tokens_out: tokensOut,
  llm_cost: Math.round(cost * 100000) / 100000
};
return [{ json: out }];

const inc = $('Parse + Classify').first().json;
const saved = $input.first().json;
const project = $('Load Project + Handover').first().json.context || {};
const sevColor = { urgent: '#dc2626', high: '#ea580c', medium: '#f59e0b', low: '#10b981' }[inc.severity] || '#6b7280';
const warrColor = inc.under_warranty ? '#10b981' : '#dc2626';
const warrText = inc.under_warranty ? 'EN GARANTIA LOE' : 'FUERA DE GARANTIA LOE';
const photos = (inc.photo_urls || []).map(u => '<a href="' + u + '">foto</a>').join(' &middot; ') || '(sin fotos)';
const html = '<h2>Incidencia post-entrega — ' + (project.project_name || '?') + '</h2>' +
  '<p><span style="background:' + sevColor + ';color:white;padding:2px 8px;border-radius:3px">' + (inc.severity || '?').toUpperCase() + '</span> ' +
  '<span style="background:' + warrColor + ';color:white;padding:2px 8px;border-radius:3px;margin-left:8px">' + warrText + ' (' + inc.loe_period + ' años)</span></p>' +
  '<p><b>Categoría:</b> ' + (inc.category || '?') + ' &middot; <b>Gremio responsable:</b> ' + (inc.responsible_trade || '?') + '</p>' +
  '<p><b>Días desde entrega:</b> ' + (inc.days_since_handover === null || inc.days_since_handover === undefined ? 'sin handover_date' : inc.days_since_handover + ' días') + '</p>' +
  '<p><b>Descripción cliente:</b><br>' + inc.description.replace(/\n/g, '<br>') + '</p>' +
  '<p><b>Análisis IA:</b><br>' + (inc.vision_summary || '?') + '</p>' +
  (inc.vision_raw && inc.vision_raw.action_recommended ? '<p><b>Acción recomendada:</b> ' + inc.vision_raw.action_recommended + '</p>' : '') +
  '<p><b>Fotos:</b> ' + photos + '</p>' +
  '<p style="font-size:12px;color:#6b7280">Incident ID: ' + saved.id + '<br>Asignar gremio: POST /webhook/aftercare-assign con {incident_id, assigned_to}<br>Marcar resuelto: POST /webhook/aftercare-resolve con {incident_id, resolution_notes, evidence_urls?}</p>';
return [{ json: { html: html, severity: inc.severity, project_name: project.project_name, incident_id: saved.id } }];

const err = $input.first().json;
const built = $('Build Vision Prompt').first().json;
const msg = (err && (err.message || (err.error && err.error.message))) || 'vision error';
return [{ json: { project_id: built.project_id, error: msg } }];
